/** Published evidence, never synthetic/live counters. Generated by publish-benchmarks.mjs. */
export interface Evidence {
  schemaVersion: 1;
  status: "measured";
  measuredAt: string;
  core: {
    players: number;
    seconds: number;
    messagesPerSecond: number;
    ackP95Ms: number;
    tickP95Ms: number;
    soaked: boolean;
  };
  aoi: { players: number; reductionPercent: number } | null;
  environment: {
    cpu: string;
    logicalCores: number;
    ramMiB: number;
    os: string;
    node: string;
    commit: string;
    artifactSha256: string;
    tickRate: number;
    topology: string;
  };
  fullGame: { players: number; status: string } | null;
  reportUrl: string;
}

export interface BenchmarkCard {
  label: string;
  value: number | null;
  decimals: number;
  note: string;
}

/** Fetches and validates the published report. Returns null when nothing trustworthy is published. */
export async function loadBenchmarks(): Promise<Evidence | null> {
  try {
    const response = await fetch("/art/benchmark/latest.json", { cache: "no-cache" });
    if (!response.ok) return null;
    const data = (await response.json()) as Evidence;
    if (
      data.schemaVersion !== 1 ||
      data.status !== "measured" ||
      !data.core.soaked ||
      !data.reportUrl.startsWith("/art/benchmark/")
    )
      return null;
    const core = [data.core.players, data.core.messagesPerSecond, data.core.ackP95Ms, data.core.tickP95Ms];
    if (core.some((v) => typeof v !== "number" || !Number.isFinite(v) || v < 0)) return null;
    return data;
  } catch {
    /* Offline or unpublished evidence keeps the honest placeholders. */
    return null;
  }
}

export function benchmarkCards(data: Evidence): BenchmarkCard[] {
  return [
    { label: "ACTIVE PLAYERS TESTED", value: data.core.players, decimals: 0, note: `${Math.round(data.core.seconds / 60)}-minute distributed soak` },
    { label: "PROTOCOL MESSAGES / SEC", value: data.core.messagesPerSecond, decimals: 0, note: "Sustained inbound + outbound" },
    { label: "P95 APPLICATION LATENCY", value: data.core.ackP95Ms, decimals: 1, note: "MOVE → authoritative ACK" },
    { label: "P95 WORLD UPDATE TIME", value: data.core.tickP95Ms, decimals: 2, note: `${data.environment.tickRate} Hz authoritative simulation` },
    {
      label: "AOI FAN-OUT REDUCTION",
      value: data.aoi?.reductionPercent ?? null,
      decimals: 1,
      note: data.aoi ? `${data.aoi.players}-player matched comparison` : "No passing paired run published",
    },
  ];
}

export function benchmarkMethodology(data: Evidence): HTMLDetailsElement {
  const details = document.createElement("details");
  details.className = "bench-method";
  const summary = document.createElement("summary");
  summary.textContent = "Test environment & methodology";
  const text = document.createElement("p");
  text.textContent = `${data.environment.cpu}, ${data.environment.logicalCores} logical cores, ${Math.round(data.environment.ramMiB / 1024)} GiB RAM, ${data.environment.os}. ${data.environment.topology} The figures describe this measured workload; they are not a hardware-independent maximum or a Render capacity claim.`;
  const full = document.createElement("p");
  full.textContent = data.fullGame
    ? `Full-game lobby/workbench load: ${data.fullGame.players} players, ${data.fullGame.status}. See the report for gates and limits.`
    : "The core result excludes the event/contract scheduler. Full-game correctness is reported separately.";
  const link = document.createElement("a");
  link.href = data.reportUrl;
  link.className = "text-link";
  link.textContent = "Read the full measured report ↗";
  details.append(summary, text, full, link);
  return details;
}
